'use strict';
const $ = (s, r=document) => r.querySelector(s);
const $$ = (s, r=document) => [...r.querySelectorAll(s)];
const home = $('#homeView'), page = $('#pageView'), nav = $('#mainNav'), notice = $('#notice');
const menuToggle = $('#menuToggle');
let noticeTimer;
let currentSession=null, sessionChecked=false;
const API_BASE=($('#apiBaseConfig')?.content||document.querySelector('meta[name="qayyum-api-base"]')?.content||'').trim().replace(/\/$/,'');
function apiToken(){try{return sessionStorage.getItem('qayyum-session-token')||''}catch{return ''}}
async function apiRequest(path,options={}){if(!API_BASE)throw new Error('API غير مضبوط؛ أضف عنوان الخادم في meta[name=\"qayyum-api-base\"].');const headers=new Headers(options.headers||{});if(apiToken())headers.set('Authorization',`Bearer ${apiToken()}`);if(options.body&&!(options.body instanceof FormData))headers.set('Content-Type','application/json');const response=await fetch(`${API_BASE}${path}`,{...options,headers});const data=response.status===204?null:await response.json().catch(()=>({}));if(!response.ok)throw new Error(data?.error||`HTTP ${response.status}`);return data}

function toast(message){notice.textContent=message;notice.classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>notice.classList.remove('show'),3300)}
function hijriDate(){try{return new Intl.DateTimeFormat('ar-SA-u-ca-islamic-umalqura',{day:'numeric',month:'long',year:'numeric'}).format(new Date())}catch{return 'التاريخ الهجري'}}
function gregDate(){return new Intl.DateTimeFormat('ar',{day:'numeric',month:'long',year:'numeric'}).format(new Date())}
