function stat(label,value,desc){return `<div class="stat-card"><span>${label}</span><strong>${value}</strong><small>${desc}</small></div>`}
function renderLibrary(){return `<div class="page-shell"><section class="paper-card"><h2>التصنيفات العلمية الرئيسية</h2><div class="card-body"><div class="grid-3">${taxonomy.map((t,i)=>`<button class="btn secondary" type="button" data-action="category-select" data-category="${t}">${String(i+1).padStart(2,'0')} · ${t}</button>`).join('')}</div></div></section>
 <div class="notice-strip warning">الفهرس المعروض هنا واجهة جاهزة للربط. لا توجد حالياً قاعدة كتب حية أو نتائج موثقة متصلة بالخادم.</div>
 <section class="paper-card"><h2>البحث المتقدم في الكتب</h2><div class="card-body"><form id="catalogForm"><div class="form-row"><div class="field"><label>عنوان الكتاب أو جزء منه</label><input id="bookQuery" placeholder="اسم الكتاب"></div><div class="field"><label>المؤلف</label><input placeholder="اسم المؤلف"></div><div class="field"><label>المذهب / المدرسة</label><select><option>جميع المدارس</option><option>إمامي اثنا عشري</option><option>سني</option><option>إباضي</option><option>زيدي</option><option>إسماعيلي</option><option>مقارن / غير محدد</option></select></div></div><div class="form-row"><div class="field"><label>التخصص</label><select><option>جميع التخصصات</option><option>الحديث والرجال</option><option>الفقه وأصوله</option><option>العقائد والكلام</option><option>التفسير وعلوم القرآن</option><option>التاريخ والسيرة</option><option>اللغة والبلاغة</option></select></div><div class="field"><label>لغة الكتاب</label><select><option>كل اللغات</option><option>العربية</option><option>الفارسية</option><option>الإنجليزية</option><option>الأردية</option><option>التركية</option></select></div><div class="field"><label>نوع المادة</label><select><option>الكل</option><option>كتاب مطبوع</option><option>مخطوط</option><option>نص رقمي</option><option>بحث علمي</option></select></div></div><div class="toolbar"><button class="btn" type="submit">بحث في الفهرس</button><button class="btn secondary" type="reset">مسح الفلاتر</button><button class="btn ghost" type="button" data-action="external-search">إعداد بحث متعدد المصادر</button></div></form></div></section>
 <section class="paper-card"><h2>النتائج</h2><div class="card-body" id="catalogResults">${demoBooks.map(b=>`<article class="book-card"><div class="book-cover">📚</div><div><h3>${b.title}</h3><p>${b.author}</p><p>${b.meta}</p><span class="chip">${b.kind}</span><div class="book-actions"><button class="btn secondary" data-action="book-detail">تفاصيل الفهرسة</button><button class="btn ghost" data-action="rights-info">حالة الإتاحة والحقوق</button></div></div></article>`).join('')}</div></section>
 <section class="grid-3">${stat('عدد المدارس','قابل للتوسع','التصنيف لا يُستنتج من اسم المؤلف')}${stat('منع التكرار','مخطط له','مطابقة العنوان والمؤلف وهوية العمل')}${stat('تنزيل الملفات','وفق الحقوق','لا تنزيل دون إذن أو ترخيص واضح')}</section>
 </div>`}
function renderResearch(){return `<div class="page-shell"><div class="notice-strip">مشاريعك البحثية خاصة بحسابك عند تسجيل الدخول، أو تحفظ محلياً على هذا الجهاز عند استخدام المكتبة دون خادم.</div><div class="grid-2"><section class="paper-card"><h2>إنشاء مشروع علمي</h2><div class="card-body"><form id="researchForm"><div class="field"><label>عنوان البحث</label><input id="researchTitle" required minlength="3" maxlength="500" placeholder="عنوان المشروع أو المسألة"></div><div class="field"><label>وصف مختصر</label><textarea id="researchDesc" maxlength="12000" placeholder="موضوع البحث وحدوده"></textarea></div><div class="field"><label>نوع المشروع</label><select id="researchType"><option value="research">بحث علمي</option><option value="study">دراسة ومطالعة</option><option value="text_edition">تحقيق نص</option><option value="evidence_comparison">مقارنة أدلة</option><option value="reading_plan">خطة قراءة</option></select></div><button class="btn" type="submit">حفظ المشروع</button></form></div></section><section class="paper-card"><h2>مشاريعي</h2><div class="card-body" id="researchProjects"><div class="empty-state">جارٍ تحميل المشاريع...</div></div></section></div><section class="paper-card" id="researchDetail" hidden><h2>هيكل البحث ومصادره</h2><div class="card-body" id="researchDetailBody"></div></section><div class="grid-3"><div class="tool-tile"><b>📑 هيكل البحث</b><p>أبواب وفصول ومباحث مع ترتيب قابل للتعديل.</p></div><div class="tool-tile"><b>🔖 إدارة المصادر</b><p>حفظ بيانات المصدر والطبعة والجزء والصفحة.</p></div><div class="tool-tile"><b>🧾 سجل النسخ</b><p>الاحتفاظ بإصدارات البحث ومراجعة التغييرات.</p></div></div></div>`}
function renderHadith(){return `<div class="page-shell"><div class="notice-strip warning">لا توجد قاعدة روايات متصلة بعد. يجب إدخال كل رواية مع مصدرها وطبعتها وموضعها، وفصل اختلاف المتون والطرق وأحكام العلماء.</div><section class="paper-card"><h2>البحث في الروايات</h2><div class="card-body"><form id="hadithForm"><div class="form-row"><div class="field"><label>نص الرواية أو عبارة منها</label><input placeholder="اكتب عبارة من المتن"></div><div class="field"><label>اسم الراوي</label><input placeholder="اسم الراوي"></div><div class="field"><label>المصدر</label><input placeholder="اسم الكتاب أو المصنف"></div></div><div class="form-row"><div class="field"><label>المدرسة الحديثية</label><select><option>جميع المدارس</option><option>مصادر إمامية</option><option>مصادر سنية</option><option>مصادر أخرى</option></select></div><div class="field"><label>نوع البحث</label><select><option>المتن والمصدر</option><option>الرواة</option><option>الأسانيد والطرق</option><option>أحكام العلماء</option></select></div></div><button class="btn" type="submit">بحث الروايات</button></form></div></section><div class="grid-3"><div class="tool-tile"><b>📜 بطاقة الرواية</b><p>النص، اختلاف الألفاظ، المصادر، الجزء والصفحة.</p></div><div class="tool-tile"><b>🔗 شبكة الأسانيد</b><p>عرض كل طريق بصورة مستقلة دون دمج تلقائي.</p></div><div class="tool-tile"><b>⚖️ أقوال الرجاليين</b><p>كل تقييم منسوب إلى قائله ومصدره وموضعه.</p></div></div><section class="paper-card"><h2>نتائج البحث</h2><div class="card-body" id="hadithResults"><div class="empty-state">أدخل شروط البحث. ستظهر النتائج بعد ربط قاعدة البيانات.</div></div></section></div>`}
function renderCalendar(){return `<div class="page-shell"><div class="calendar-banner"><div class="calendar-date"><span>التاريخ الهجري · الافتراضي</span><strong>${hijriDate()}</strong><span>يعرض حسب تقويم أم القرى في المتصفح، ويحتاج ضبط المرجعية المعتمدة للتواريخ المحلية</span></div><div class="calendar-date"><span>التاريخ الميلادي</span><strong>${gregDate()}</strong><span>للمقارنة فقط</span></div></div><div class="notice-strip">قد يختلف ثبوت بداية الشهر أو تاريخ المناسبة بين المراجع والبلدان. ستُعرض الاختلافات ومصادر كل تاريخ بوضوح، ولا يُفرض تاريخ واحد على الجميع.</div><div class="grid-2"><section class="paper-card"><h2>تفضيلات التقويم</h2><div class="card-body"><label class="field"><span>طريقة عرض التاريخ</span><select id="calendarMode"><option value="hijri">الهجري أولاً ثم الميلادي</option><option value="gregorian">الميلادي أولاً ثم الهجري</option></select></label><label class="field"><span>مرجع اعتماد التاريخ</span><select id="calendarAuthority"><option value="show_variations">عرض الاختلافات مع المصادر</option><option value="user_authority">إعداد مرجعي يحدده المستخدم</option><option value="umm_al_qura">تقويم أم القرى للعرض التقريبي</option></select></label><button class="btn" data-action="save-calendar">حفظ التفضيلات بالحساب</button></div></section><section class="paper-card"><h2>المناسبات القادمة</h2><div class="card-body"><div id="calendarEventsList" class="empty-state">جارٍ تحميل المناسبات المعتمدة…</div></div></section></div><section class="paper-card"><h2>اقتراح مناسبة للمراجعة العلمية</h2><div class="card-body"><form id="eventForm"><div class="form-row"><div class="field"><label>اسم المناسبة</label><input id="eventTitle" required maxlength="300" placeholder="اسم المناسبة"></div><div class="field"><label>التاريخ الهجري</label><input id="eventHijri" maxlength="80" placeholder="مثال: ١٥ شعبان"></div><div class="field"><label>نوع المناسبة</label><select id="eventKind"><option value="birth">ولادة</option><option value="martyrdom">شهادة / وفاة</option><option value="historical">حدث تاريخي</option><option value="general">مناسبة عامة</option></select></div></div><div class="form-row"><div class="field"><label>التاريخ الميلادي والوقت (اختياري)</label><input id="eventStartsAt" type="datetime-local"></div><div class="field"><label>طريقة حساب التاريخ</label><input id="eventCalendarMethod" maxlength="80" placeholder="مثلاً: وفق مصدر محدد"></div></div><div class="field"><label>المصدر وملاحظة اختلاف التاريخ</label><textarea id="eventDescription" required maxlength="5000" placeholder="اذكر المصدر والطبعة والصفحة، وأي اختلاف في التاريخ"></textarea></div><button class="btn" type="submit">إرسال الاقتراح للمراجعة</button><p class="muted">لا تظهر المناسبة للزوار إلا بعد مراجعة المالك واعتمادها.</p></form></div></section></div>`}

function renderStudy(){return `<div class="page-shell"><div class="notice-strip">الملاحظات والاقتباسات خاصة افتراضياً. في وضع الواجهة الثابتة تُحفظ محلياً على هذا الجهاز؛ بعد إعداد API يمكن مزامنتها بحساب المستخدم.</div><div class="grid-3"><div class="tool-tile"><b>📖 دفتر المطالعة</b><p>تدوين الفوائد ومتابعة آخر موضع قراءة.</p><button class="btn secondary" data-action="open-notes">فتح الدفتر</button></div><div class="tool-tile"><b>🔬 دفتر التحقيق</b><p>مقارنة النسخ وإثبات الفروق ومصادر النصوص.</p><button class="btn secondary" data-action="open-investigation">فتح دفتر التحقيق</button></div><div class="tool-tile"><b>🧷 الاقتباسات والحواشي</b><p>حفظ النص مع الجزء والصفحة والطبعة.</p><button class="btn secondary" data-action="open-citations">إدارة الاقتباسات</button></div><div class="tool-tile"><b>📚 خطة القراءة</b><p>تنظيم الكتب والدروس حسب التخصص.</p><button class="btn secondary" data-action="reading-plan">إنشاء خطة</button></div><div class="tool-tile"><b>🧠 المصطلحات العلمية</b><p>حفظ تعريفاتك ومراجعتها ضمن الملاحظات.</p><button class="btn secondary" data-action="terms">بطاقات المصطلحات</button></div><div class="tool-tile"><b>📝 تصدير البحث</b><p>تجهيز المحتوى لاحقاً بصيغ Word وPDF.</p><button class="btn secondary" data-action="export-info">خيارات التصدير</button></div></div><section class="paper-card" id="studyWorkspace"><h2>دفتر الملاحظات والاقتباسات</h2><div class="card-body"><form id="noteForm"><div class="form-row"><div class="field"><label for="noteKind">نوع السجل</label><select id="noteKind"><option value="note">ملاحظة</option><option value="quote">اقتباس</option><option value="citation">إحالة مصدرية</option><option value="research">مادة بحثية / تحقيق</option></select></div><div class="field"><label for="noteTitle">العنوان</label><input id="noteTitle" required placeholder="عنوان الفائدة أو الاقتباس"></div></div><div class="field"><label for="noteBody">النص أو بيانات الإحالة</label><textarea id="noteBody" required placeholder="النص المنقول أو الملاحظة العلمية"></textarea></div><div class="field"><label for="noteLocator">المصدر والطبعة والجزء والصفحة / الموضع</label><input id="noteLocator" placeholder="اسم الكتاب، الطبعة، ج 1، ص 25"></div><button class="btn" type="submit">حفظ في دفتر هذا الجهاز</button></form><div id="savedNotes" class="notice-strip">لا توجد ملاحظات محفوظة.</div></div></section></div>`}
const levels=[1000,2000,4000,8000,16000,32000,64000,128000,256000,512000];
function renderGroups(){return `<div class="page-shell"><div class="notice-strip">المجموعات والقنوات العلمية تخضع لموافقة المالك قبل النشر. المنشورات الجديدة تمر بالمراجعة، والقنوات لا ينشر فيها إلا المدير أو المشرف المعتمد.</div><div class="grid-3">${stat('المستويات','10','لا توجد مستويات بعد العاشر')}${stat('اعتماد الترقية','يدوي','لا يُمنح الوسام تلقائياً')}${stat('مراجعة المالك','إلزامية','إنشاء المجموعات والقنوات')}</div><section class="paper-card"><h2>إنشاء مجموعة أو قناة علمية</h2><div class="card-body"><form id="communitySpaceForm"><div class="form-row"><div class="field"><label>النوع</label><select id="communityKind"><option value="group">مجموعة نقاش علمي</option><option value="channel">قناة نشر علمي</option></select></div><div class="field"><label>اسم المجموعة أو القناة</label><input id="communityName" required minlength="3" maxlength="240"></div><div class="field"><label>الخصوصية</label><select id="communityPrivacy"><option value="public">عامة</option><option value="private">خاصة بطلب انضمام</option></select></div></div><div class="field"><label>الوصف والأهداف العلمية</label><textarea id="communityDescription" maxlength="4000" required></textarea></div><button class="btn" type="submit">إرسال طلب الإنشاء للمالك</button></form></div></section><section class="paper-card"><h2>المجموعات والقنوات المنشورة</h2><div class="card-body"><div class="toolbar"><input id="communitySearch" placeholder="ابحث عن مجموعة أو قناة"><button class="btn secondary" data-action="community-load">بحث وتحديث</button></div><div id="communitySpacesList" class="empty-state">سجّل الدخول لعرض المساحات المعتمدة.</div><div id="communityFeed"></div></div></section><section class="paper-card"><h2>سلم مستويات المجموعات والقنوات</h2><div class="card-body"><div class="level-list">${levels.map((p,i)=>`<div class="level"><span>المستوى ${i+1}</span><b>${p.toLocaleString('en-US')}</b><small>نقطة للترقية</small><div class="progress"><i></i></div><small>${['وسام البداية','وسام النشاط','وسام التفاعل','وسام التميز','وسام النخبة','وسام الريادة','وسام الاحتراف','وسام الإبداع','وسام السيادة','وسام القيّوم'][i]}</small></div>`).join('')}</div><p class="muted">الأوزان: 40% البحوث والمحتوى العلمي، 30% الفعاليات والمبادرات، 20% التفاعل الحقيقي، 10% نمو الأعضاء. اعتماد النقاط والترقيات يبقى خاضعاً للمراجعة.</p></div></section>${currentSession?.accountType==='owner'?`<section class="paper-card"><h2>طلبات إنشاء المجموعات والقنوات · مركز المالك</h2><div class="card-body"><button class="btn secondary" data-action="community-owner-queue">تحميل الطلبات المعلقة</button><div id="communityOwnerQueue"></div></div></section>`:''}</div>`}
function renderAssistant(){return `<div class="page-shell"><div class="notice-strip warning">المساعد العلمي غير متصل بنموذج ذكاء اصطناعي أو فهرس مصادر في هذه النسخة. لن تُعرض إجابات أو مراجع مختلقة.</div><section class="paper-card"><h2>إعداد نطاق المصادر</h2><div class="card-body"><form id="assistantForm"><div class="field"><label>مصادر الإجابة</label><select id="assistantScope" required><option value="">اختر نطاق المصادر قبل المتابعة</option><option value="library">مصادر مكتبة القيّوم الموثقة فقط</option><option value="external">مصادر المكتبة والمصادر الخارجية مع تمييزها</option></select></div><div class="field"><label>سؤالك العلمي</label><textarea id="assistantQuestion" required placeholder="اكتب المسألة أو السؤال العلمي"></textarea></div><button class="btn" type="submit">إعداد السؤال (غير متصل)</button></form></div></section><div class="grid-3"><div class="tool-tile"><b>📚 توثيق المصادر</b><p>اسم المصدر والطبعة والجزء والصفحة.</p></div><div class="tool-tile"><b>⚖️ فصل المنقول عن التحليل</b><p>تمييز النص الأصلي عن الشرح والاستنتاج.</p></div><div class="tool-tile"><b>🔍 درجة التحقق</b><p>بيان ما ثبت وما يحتاج مراجعة علمية.</p></div></div></div>`}
function renderReader(){return `<div class="page-shell"><div class="notice-strip">قارئ مكتبة القيّوم: تُعرض النسخ المعتمدة داخل الموقع بهوية المكتبة، ولا يُحوَّل القارئ إلى مواقع خارجية.</div><section class="paper-card"><h2>فتح كتاب من مكتبة القيّوم</h2><div class="card-body"><div class="field"><label for="readerLibraryUrl">رابط ملف الكتاب المستضاف ضمن القيّوم</label><input id="readerLibraryUrl" type="url" placeholder="/library-files/book.pdf أو رابط خادم القيّوم"></div><div class="toolbar"><button class="btn" type="button" data-action="reader-open-url">فتح داخل القيّوم</button><span class="muted">يُقبل رابط من نفس الموقع أو من خادم القيّوم المضبوط فقط.</span></div><hr><div class="field"><label for="readerFile">أو افتح ملفاً من جهازك للتجربة</label><input id="readerFile" type="file" accept="application/pdf,.pdf,application/epub+zip,.epub"></div><p class="muted">الملف المحلي لا يُرفع تلقائياً.</p><div class="toolbar"><button class="btn secondary" data-action="reader-prev">السابق</button><button class="btn secondary" data-action="reader-next">التالي</button><button class="btn secondary" data-action="reader-zoom-in">تكبير +</button><button class="btn secondary" data-action="reader-zoom-out">تصغير −</button><button class="btn secondary" data-action="reader-night">الوضع الليلي</button><button class="btn secondary" data-action="reader-bookmark">إضافة علامة</button><button class="btn secondary" data-action="reader-note">ملاحظة على الموضع</button></div><div class="field" style="max-width:220px;margin-top:12px"><label>رقم الصفحة</label><input type="number" min="1" value="1" id="readerPage"></div><div id="readerStatus" class="muted" aria-live="polite">لم يتم فتح كتاب بعد.</div><button class="btn" type="button" data-action="reader-upload">إرسال نسخة إلى حجر المراجعة (يتطلب الدخول)</button></div></section><div class="paper-card" id="readerCanvas"><h2>قارئ مكتبة القيّوم</h2><div class="card-body" id="readerContent"><div class="empty-state">اختر كتاباً معتمداً لقراءته هنا داخل المكتبة.</div></div></div><section class="paper-card"><h2>علاماتك وملاحظات القراءة</h2><div class="card-body" id="readerSavedItems">${renderReaderSavedItems()}</div></section></div>`}
function renderReaderSavedItems(){const marks=readStore('qayyum-reader-bookmarks'),notes=readStore('qayyum-reader-notes');return [...marks.map(x=>({...x,type:'علامة'})),...notes.map(x=>({...x,type:'ملاحظة'}))].sort((a,b)=>b.at-a.at).slice(0,60).map(x=>`<article class="notice-strip"><b>${x.type} · ${escapeHtml(String(x.page||''))}</b><p>${escapeHtml(x.note||'موضع قراءة محفوظ')}</p><small>${new Date(x.at).toLocaleString('ar')}</small></article>`).join('')||'<div class="empty-state">لا توجد علامات أو ملاحظات بعد.</div>'}
async function loadReaderLibrary(name,buffer){const box=$('#readerContent'),status=$('#readerStatus');if(!box)return;const ext=String(name).split('.').pop().toLowerCase();if(!['pdf','epub'].includes(ext)){status.textContent='صيغة غير مدعومة؛ المتاح PDF وEPUB.';return}box.innerHTML='<div class="empty-state">جارٍ تجهيز صفحات الكتاب…</div>';window.readerBytes=buffer;window.readerType=ext;window.readerScale=1;window.readerPageNo=1;window.readerDoc=null;window.readerEpub=null;status.textContent=`${name} · قارئ مكتبة القيّوم`;try{if(ext==='pdf'){await loadReaderScript('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js');if(!window.pdfjsLib)throw new Error('تعذر تحميل محرك PDF');window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';window.readerDoc=await window.pdfjsLib.getDocument({data:new Uint8Array(buffer)}).promise;box.innerHTML='<div class="reader-pdf-stage"><canvas id="readerPdfPage"></canvas></div>';await renderPdfPage(1);status.textContent=`${name} · ${window.readerDoc.numPages} صفحة · داخل مكتبة القيّوم`}else{await loadReaderScript('https://cdn.jsdelivr.net/npm/epubjs/dist/epub.min.js');if(!window.ePub)throw new Error('تعذر تحميل محرك EPUB');box.innerHTML='<div id="epubReader" class="reader-epub-stage"></div>';window.readerEpub=window.ePub(buffer);window.readerEpub.renderTo('epubReader',{width:'100%',height:'75vh',flow:'paginated'});await window.readerEpub.display();status.textContent=`${name} · قراءة EPUB داخل مكتبة القيّوم`}}catch(err){box.innerHTML=`<div class="empty-state">تعذر عرض الكتاب: ${escapeHtml(err.message)}. تحقق من سلامة الملف واتصال الإنترنت.</div>`;status.textContent='تعذر فتح النسخة.'}}
function loadReaderScript(src){return new Promise((resolve,reject)=>{const existing=[...document.scripts].find(x=>x.src===src);if(existing){if(src.includes('pdf.min')&&window.pdfjsLib||src.includes('epub.min')&&window.ePub)return resolve();existing.addEventListener('load',resolve,{once:true});existing.addEventListener('error',reject,{once:true});return}const script=document.createElement('script');script.src=src;script.onload=resolve;script.onerror=()=>reject(new Error('فشل تحميل محرك القراءة'));document.head.append(script)})}
async function renderPdfPage(pageNo){if(!window.readerDoc)return;const page=await window.readerDoc.getPage(Math.max(1,Math.min(window.readerDoc.numPages,pageNo)));window.readerPageNo=pageNo;const canvas=$('#readerPdfPage'),ctx=canvas.getContext('2d'),viewport=page.getViewport({scale:window.readerScale||1.2});canvas.width=viewport.width;canvas.height=viewport.height;canvas.style.width='100%';canvas.style.maxWidth='100%';await page.render({canvasContext:ctx,viewport}).promise;const input=$('#readerPage');if(input)input.value=pageNo}
async function openLocalReader(file){if(!file)return;const ext=file.name.split('.').pop().toLowerCase();if(!['pdf','epub'].includes(ext)){toast('نوع الملف غير مدعوم.');return}const buffer=await file.arrayBuffer();window.readerLocalFile=file;await loadReaderLibrary(file.name,buffer);try{localStorage.setItem('qayyum-last-reader-file',file.name)}catch{}}
async function openLibraryReaderUrl(raw){const status=$('#readerStatus');try{const u=new URL(raw,location.href),allowed=u.origin===location.origin||(API_BASE&&u.origin===new URL(API_BASE).origin);if(!allowed)throw new Error('يجب أن تكون النسخة مستضافة على موقع القيّوم أو خادمه، وليس على موقع خارجي.');status.textContent='جارٍ جلب نسخة مكتبة القيّوم…';const headers={};if(API_BASE&&u.origin===new URL(API_BASE).origin&&apiToken())headers.Authorization=`Bearer ${apiToken()}`;const response=await fetch(u.href,{headers,credentials:'same-origin'});if(!response.ok)throw new Error(`تعذر جلب الملف (${response.status})`);const blob=await response.blob();await loadReaderLibrary(u.pathname.split('/').pop()||'book.pdf',await blob.arrayBuffer())}catch(err){status.textContent=err.message;toast(err.message)}}

function renderPersonal(){return `<div class="page-shell"><div class="grid-3"><div class="tool-tile"><b>📚 رفوفي</b><p>كتب محفوظة ومجموعات قراءة خاصة.</p></div><div class="tool-tile"><b>🕘 سجل القراءة</b><p>آخر موضع قراءة ونسبة التقدم.</p></div><div class="tool-tile"><b>🔖 العلامات والاقتباسات</b><p>النصوص المحفوظة والحواشي الشخصية.</p></div></div><section class="paper-card"><h2>مكتبتي الشخصية</h2><div class="card-body"><div class="empty-state">سجّل الدخول بعد تفعيل الخادم لتظهر رفوفك وملاحظاتك ومجموعاتك الخاصة.</div></div></section></div>`}
function renderNotifications(){const items=[['calendar','مناسبة إسلامية','تذكير بالمناسبات حسب التقويم الذي تختاره'],['book','كتاب جديد','تنبيه عند إضافة كتاب موثق'],['research','البحوث','الردود والمراجعات على مشاريعك'],['community','المجموعات والقنوات','التحديثات والأنشطة المعتمدة'],['security','الأمان','الدخول من جهاز جديد والتنبيهات الأمنية'],['admin','الإدارة','البلاغات والقرارات والطلبات الإدارية']];return `<div class="page-shell"><div class="notice-strip">تظهر هنا إشعارات الحساب الفعلية. إشعارات المتصفح والهاتف تحتاج إعداد خدمة إرسال مستقلة وموافقتك الصريحة.</div><section class="paper-card"><h2>قنوات الإشعار</h2><div class="card-body"><div class="settings-list">${items.map(x=>`<div class="settings-item"><label><span><b>${x[1]}</b><br><small>${x[2]}</small></span><input type="checkbox" class="notification-pref" data-kind="${x[0]}" checked></label></div>`).join('')}</div><button class="btn" data-action="save-notification-preferences">حفظ تفضيلات الإشعارات</button></div></section><section class="paper-card"><div class="toolbar" style="justify-content:space-between"><h2>سجل الإشعارات</h2><button class="btn secondary" data-action="notifications-read-all">تحديد الكل كمقروء</button></div><div class="card-body"><div id="notificationsList" class="empty-state">سجّل الدخول لعرض إشعارات حسابك.</div></div></section></div>`}

function renderAdminDashboard(){return `<div class="page-shell"><div class="notice-strip">هذه مساحة الإدارة المفعّلة للحسابات التي منحها المالك صلاحية الإدارة. لا تتضمن مركز المالك أو إدارة الحسابات والصلاحيات الحساسة.</div><section class="paper-card"><h2>صلاحيات حسابك</h2><div class="card-body"><p>تُحدَّث صلاحياتك من حساب المالك، ويُتحقق منها على الخادم عند كل طلب. إذا سُحبت صلاحية الإدارة أو أُوقف الحساب ينتهي الوصول الإداري مباشرة.</p><div class="toolbar"><button class="btn secondary" data-action="admin-calendar-load">عرض المناسبات المرسلة للمراجعة</button><button class="btn" data-action="admin-workspace-load">المشاريع والمهام والاجتماعات</button><button class="btn secondary" data-action="admin-moderation-load">البلاغات والشكاوى والاستئناف</button></div><div id="adminWorkspacePanel"></div><div id="adminCalendarQueue" class="empty-state">اضغط لعرض قائمة المناسبات المعلقة، إن كانت ضمن صلاحياتك.</div><div id="adminModerationPanel"></div></div></section></div>`}
function renderDashboard(){return `<div class="page-shell"><div class="notice-strip warning">مركز المالك خاص بحساب المالك وحده. مركز التحكم مرتبط بواجهات API للمراجعة. الإحصائيات غير معروضة حتى تتوفر قاعدة بيانات فعلية.</div><div class="grid-4">${stat('الكتب','—','تظهر بعد ربط الفهرس')}${stat('الأعضاء','—','بيانات الخادم غير متصلة')}${stat('المجموعات والقنوات','—','تخضع لموافقة المالك')}${stat('طلبات المراجعة','—','تُدار من قاعدة البيانات')}</div><div class="grid-2"><section class="dark-card"><h2>أقسام مركز التحكم</h2><div class="card-body"><div class="toolbar"><button class="btn" data-action="admin-section" data-section="catalog">إدارة الكتب والفهرس</button><button class="btn" data-action="admin-section" data-section="members">الأعضاء والحسابات</button><button class="btn" data-action="admin-section" data-section="staff">الأقسام والموظفون</button><button class="btn" data-action="admin-section" data-section="reports">البلاغات والاستئناف</button><button class="btn" data-action="admin-section" data-section="spaces">المجموعات والقنوات</button><button class="btn" data-action="admin-section" data-section="backups">النسخ الاحتياطية</button><button class="btn" data-action="admin-section" data-section="workspace">المشاريع والمهام والاجتماعات</button></div></div></section><section class="dark-card"><h2>سجل الأمان والعمليات</h2><div class="card-body"><p>تسجيل الدخول ومحاولاته والأجهزة النشطة.</p><p>تسجيل كل إجراء إداري وسببه ومنفذه.</p><p>المالك وحده ينشئ الأقسام ويمنح الصلاحيات أو يسحبها.</p><p>لا يستطيع المدير رفع صلاحياته بنفسه.</p></div></section></div><section class="paper-card"><div class="toolbar" style="justify-content:space-between"><h2>مراجعة المناسبات المقترحة</h2><button class="btn secondary" data-action="admin-calendar-load">تحميل قائمة المراجعة</button></div><div class="card-body"><div id="adminCalendarQueue" class="empty-state">اضغط تحميل قائمة المراجعة لعرض المناسبات المعلقة.</div></div></section><section class="paper-card"><div id="ownerWorkspacePanel"></div><h2>التقارير</h2><div class="card-body"><div class="toolbar"><button class="btn secondary" data-action="report-info">تقرير يومي</button><button class="btn secondary" data-action="report-info">تقرير أسبوعي</button><button class="btn secondary" data-action="report-info">تقرير شهري</button><button class="btn secondary" data-action="report-info">تقرير سنوي</button></div><p class="muted">تصدير PDF وExcel يتطلب ربط خدمة التقارير بالخادم.</p></div></section><section id="adminManagementPanel"></section></div>`}
function renderLogin(){return `<div class="page-shell"><div class="notice-strip warning">تسجيل الدخول يعمل بعد ضبط عنوان API وربط قاعدة البيانات. استخدم HTTPS في الخادم المنشور.</div><div class="grid-2"><section class="paper-card"><h2>دخول الحساب</h2><div class="card-body"><form id="loginForm"><div class="field"><label for="loginEmail">البريد الإلكتروني</label><input id="loginEmail" type="email" autocomplete="username" required placeholder="البريد الإلكتروني"></div><div class="field"><label for="loginPassword">كلمة المرور</label><input id="loginPassword" type="password" autocomplete="current-password" minlength="12" required placeholder="كلمة المرور"></div><button class="btn" type="submit">تسجيل الدخول</button></form><p id="authStatus" class="muted" aria-live="polite"></p></div></section><section class="paper-card"><h2>إنشاء حساب</h2><div class="card-body"><form id="registerForm"><div class="field"><label for="registerName">الاسم الظاهر</label><input id="registerName" required minlength="2" maxlength="160"></div><div class="field"><label for="registerEmail">البريد الإلكتروني</label><input id="registerEmail" type="email" required></div><div class="field"><label for="registerPassword">كلمة المرور (12 محرفاً على الأقل)</label><input id="registerPassword" type="password" required minlength="12" maxlength="72" autocomplete="new-password"></div><button class="btn secondary" type="submit">إنشاء حساب</button></form><p class="muted">إنشاء الحساب متاح عند تشغيل API. حساب المالك يُنشأ منفصلاً بأداة إعداد آمنة.</p></div></section></div></div>`}
async function loadAdminWorkspace(){const host=$('#adminWorkspacePanel')||$('#ownerWorkspacePanel');if(!host)return;if(!API_BASE||!apiToken()){host.textContent='سجّل الدخول بحساب إداري مفعّل.';return}host.innerHTML='<div class="empty-state">جارٍ تحميل مساحة العمل...</div>';try{const [summary,projects,meetings,reports]=await Promise.all([apiRequest('/api/admin/workspace/summary'),apiRequest('/api/admin/workspace/projects'),apiRequest('/api/admin/workspace/meetings'),apiRequest('/api/admin/workspace/reports')]);host.innerHTML=`<section class="paper-card"><h2>مساحة العمل الإدارية</h2><div class="card-body"><p>المشاريع: ${summary.projects.total} · النشطة: ${summary.projects.active} · الاجتماعات القادمة: ${summary.upcomingMeetings}</p><div class="chips-row">${summary.tasks.map(t=>`<span class="chip">${escapeHtml(t.status)}: ${t.count}</span>`).join('')||'<span class="muted">لا توجد مهام مسجلة</span>'}</div><div class="toolbar"><button class="btn" data-action="workspace-project-create">إنشاء مشروع</button>${currentSession?.accountType==='owner'?'<button class="btn secondary" data-action="workspace-meeting-create">إنشاء اجتماع نصي</button>':''}<button class="btn secondary" data-action="workspace-report-create">إنشاء تقرير</button></div><h3>المشاريع</h3>${projects.items.map(p=>`<article class="notice-strip"><b>${escapeHtml(p.title)}</b><p>${escapeHtml(p.description||'')} · ${escapeHtml(p.status)} · المهام ${p.done_count}/${p.task_count}${p.due_at?` · الاستحقاق ${new Date(p.due_at).toLocaleDateString('ar')}`:''}</p><div class="toolbar"><button class="btn secondary" data-action="workspace-task-list" data-id="${p.id}">عرض المهام</button><button class="btn ghost" data-action="workspace-task-create" data-id="${p.id}">إضافة مهمة</button></div><div id="workspaceTasks-${p.id}"></div></article>`).join('')||'<div class="empty-state">لا توجد مشاريع متاحة لحسابك.</div>'}<h3>الاجتماعات النصية</h3>${meetings.items.map(m=>`<article class="notice-strip"><b>${escapeHtml(m.title)}</b><p>${new Date(m.starts_at).toLocaleString('ar')} · ${escapeHtml(m.status)}</p><button class="btn secondary" data-action="workspace-meeting-open" data-id="${m.id}">فتح محضر الاجتماع</button><div id="meetingMessages-${m.id}"></div></article>`).join('')||'<p class="muted">لا توجد اجتماعات مسندة أو قادمة.</p>'}<h3>التقارير المحفوظة</h3>${reports.items.map(r=>`<article class="notice-strip"><b>${escapeHtml(r.report_kind)}</b><p>${escapeHtml(r.period_start)} إلى ${escapeHtml(r.period_end)} · ${new Date(r.created_at).toLocaleString('ar')}</p><details><summary>عرض ملخص التقرير</summary><pre class="report-snapshot">${escapeHtml(JSON.stringify(r.snapshot,null,2))}</pre></details></article>`).join('')||'<p class="muted">لا توجد تقارير محفوظة.</p>'}</div></section>`}catch(err){host.textContent=`تعذر تحميل مساحة العمل: ${err.message}`}}
async function loadAdminModeration(){const host=$('#adminModerationPanel')||$('#adminManagementPanel');if(!host)return;host.innerHTML='<div class="empty-state">جارٍ تحميل البلاغات والشكاوى والاستئناف...</div>';try{const [reports,appeals,tickets]=await Promise.all([apiRequest('/api/admin/moderation/reports'),apiRequest('/api/admin/moderation/appeals'),apiRequest('/api/admin/support/tickets')]);host.innerHTML=`<section class="paper-card"><h2>البلاغات</h2><div class="card-body">${reports.items.map(r=>`<article class="notice-strip"><b>${escapeHtml(r.violation_kind)} · ${escapeHtml(r.severity)}</b><p>${escapeHtml(r.target_kind)}: ${escapeHtml(r.target_id)} · ${escapeHtml(r.status)} · ${escapeHtml(r.reporter||'')}</p><p>${escapeHtml(r.description)}</p><div class="toolbar"><button class="btn secondary" data-action="moderation-decide" data-id="${r.id}" data-kind="warning">إنذار</button><button class="btn secondary" data-action="moderation-decide" data-id="${r.id}" data-kind="restrict">تقييد</button><button class="btn ghost" data-action="moderation-decide" data-id="${r.id}" data-kind="dismiss">رفض البلاغ</button></div></article>`).join('')||'<p class="muted">لا توجد بلاغات معلقة.</p>'}</div></section><section class="paper-card"><h2>طلبات الاستئناف</h2><div class="card-body">${appeals.items.map(a=>`<article class="notice-strip"><b>${escapeHtml(a.appellant)} · ${escapeHtml(a.decision_kind)}</b><p>${escapeHtml(a.appeal_text)}</p><div class="toolbar"><button class="btn" data-action="appeal-review" data-id="${a.id}" data-status="accepted">قبول الاستئناف</button><button class="btn secondary" data-action="appeal-review" data-id="${a.id}" data-status="rejected">رفض الاستئناف</button><button class="btn ghost" data-action="appeal-review" data-id="${a.id}" data-status="returned">إرجاع للمراجعة</button></div></article>`).join('')||'<p class="muted">لا توجد استئنافات معلقة.</p>'}</div></section><section class="paper-card"><h2>طلبات الدعم والشكاوى</h2><div class="card-body">${tickets.items.map(t=>`<article class="notice-strip"><b>#${t.ticket_no} · ${escapeHtml(t.subject)}</b><p>${escapeHtml(t.requester)} · ${escapeHtml(t.category)} · ${escapeHtml(t.priority)} · ${escapeHtml(t.status)}</p><div class="toolbar"><button class="btn secondary" data-action="ticket-assign" data-id="${t.id}">استلام الطلب</button><button class="btn ghost" data-action="ticket-status" data-id="${t.id}" data-status="resolved">إنهاء الطلب</button><button class="btn ghost" data-action="ticket-thread" data-id="${t.id}">عرض المحادثة</button><button class="btn ghost" data-action="ticket-reply" data-id="${t.id}">الرد على المستخدم</button></div><div id="adminTicketThread-${t.id}"></div></article>`).join('')||'<p class="muted">لا توجد طلبات دعم.</p>'}</div></section>`}catch(err){host.textContent=`تعذر تحميل مركز المراجعة: ${err.message}`}}
async function loadAdminMembers(){const host=$('#adminManagementPanel');if(!host)return;host.innerHTML='<div class="empty-state">جارٍ تحميل الأعضاء...</div>';try{const d=await apiRequest('/api/admin/members');host.innerHTML=`<section class="paper-card"><h2>الأعضاء والحسابات</h2><div class="card-body"><div class="field"><label>بحث بالاسم أو اسم المستخدم أو الرقم</label><input id="adminMemberSearch" placeholder="اكتب للبحث"></div><div id="adminMembersList">${d.items.map(m=>`<article class="notice-strip"><b>${escapeHtml(m.display_name||m.username||'عضو بلا اسم')}</b><p>الرقم: ${escapeHtml(m.public_id||'—')} · نوع الحساب: ${escapeHtml(m.account_type)} · الحالة: ${escapeHtml(m.status)} · الأدوار: ${escapeHtml((m.roles||[]).join('، ')||'لا توجد')}</p><div class="toolbar">${m.account_type!=='owner'?`<button class="btn secondary" data-action="member-access" data-id="${escapeHtml(m.id)}" data-type="${escapeHtml(m.account_type)}">${m.account_type==='admin'?'إلغاء صلاحية الإدارة':'تفعيل كحساب إداري'}</button>`:''}${m.account_type==='member'?`<button class="btn secondary" data-action="member-roles" data-id="${escapeHtml(m.id)}" data-roles="${escapeHtml((m.roles||[]).join(','))}">تعديل الأدوار</button>`:''}<button class="btn ghost" data-action="member-status" data-id="${escapeHtml(m.id)}" data-status="${escapeHtml(m.status)}">تغيير الحالة</button></div></article>`).join('')||'<div class="empty-state">لا يوجد أعضاء مطابقون.</div>'}</div></div></section>`;const search=$('#adminMemberSearch');search?.addEventListener('input',()=>{const term=search.value.trim().toLowerCase();$$('#adminMembersList article').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(term))})}catch(err){host.textContent=`تعذر تحميل الأعضاء: ${err.message}`}}
async function loadAdminStaff(){const host=$('#adminManagementPanel');if(!host)return;host.innerHTML='<div class="empty-state">جارٍ تحميل الأقسام والموظفين...</div>';try{const d=await apiRequest('/api/admin/departments');host.innerHTML=`<section class="paper-card"><div class="toolbar" style="justify-content:space-between"><h2>الأقسام الإدارية</h2><button class="btn" data-action="department-create">إنشاء قسم</button></div><div class="card-body">${d.items.map(x=>`<article class="notice-strip"><b>${escapeHtml(x.name)}</b><p>${escapeHtml(x.description||'')} · الحالة: ${escapeHtml(x.status)} · المكلفون: ${x.assigned_count}</p>${(x.assignments||[]).map(a=>`<p class="muted">${escapeHtml(a.display_name||a.user_id)} · ${escapeHtml(a.role)} <button class="btn ghost" data-action="department-unassign" data-id="${x.id}" data-user-id="${escapeHtml(a.user_id)}" data-role="${escapeHtml(a.role)}">سحب الإسناد</button></p>`).join('')}<div class="toolbar"><button class="btn secondary" data-action="department-assign" data-id="${x.id}">إسناد موظف</button><button class="btn ghost" data-action="department-status" data-id="${x.id}" data-status="${escapeHtml(x.status)}">تغيير الحالة</button></div></article>`).join('')||'<div class="empty-state">لا توجد أقسام بعد. أنشئ أول قسم.</div>'}</div></section>`}catch(err){host.textContent=`تعذر تحميل الأقسام: ${err.message}`}}
function renderSettings(){return `<div class="page-shell"><div class="grid-2"><section class="paper-card"><h2>اللغة والاتجاه</h2><div class="card-body"><div class="field"><label>لغة الواجهة</label><select id="uiLanguage"><option>العربية</option><option>فارسی</option><option>English</option><option>اردو</option><option>Türkçe</option><option>Français</option><option>Bahasa Indonesia</option></select></div><p class="muted">النظام مصمم لدعم لغات إضافية وواجهات RTL وLTR. اختيار اللغة لا يغيّر لغة الكتاب الأصلي.</p></div></section><section class="paper-card"><h2>إمكانية الوصول</h2><div class="card-body"><label class="check-row"><input type="checkbox" id="largeText"> تكبير النص</label><label class="check-row"><input type="checkbox" id="highContrast"> تباين أعلى</label><label class="check-row"><input type="checkbox" id="reduceMotion"> تقليل الحركة</label><button class="btn" data-action="accessibility-save">حفظ التفضيلات لهذا الجهاز</button></div></section></div><section class="paper-card"><h2>الخصوصية</h2><div class="card-body"><label class="check-row"><input type="checkbox" checked> الملف الشخصي عام (قابل للتغيير)</label><label class="check-row"><input type="checkbox" checked> حفظ تقدم القراءة على الحساب عند تفعيل الخادم</label><label class="check-row"><input type="checkbox"> السماح بمشاركة الملاحظات العلمية</label><p class="muted">إعدادات الحساب الحقيقية تُحفظ على الخادم بعد تسجيل الدخول.</p></div></section></div>`}
function renderContact(){return `<div class="page-shell"><section class="paper-card"><h2>إرسال طلب دعم أو شكوى</h2><div class="card-body"><form id="supportForm"><div class="form-row"><div class="field"><label>نوع الطلب</label><select id="supportCategory"><option value="technical">مشكلة تقنية</option><option value="catalog">تصحيح بيانات كتاب</option><option value="rights">حقوق نشر وإتاحة</option><option value="account">مشكلة حساب</option><option value="suggestion">اقتراح تطوير</option><option value="other">أخرى</option></select></div><div class="field"><label>عنوان الطلب</label><input id="supportSubject" required maxlength="300" placeholder="عنوان مختصر"></div></div><div class="field"><label>التفاصيل</label><textarea id="supportBody" required maxlength="12000" placeholder="اشرح الطلب بالتفصيل"></textarea></div><button class="btn" type="submit">إرسال الطلب</button></form><div id="mySupportTickets" class="card-body"><p class="muted">سجّل الدخول لمتابعة طلباتك السابقة.</p></div><div id="myModerationDecisions" class="card-body"></div></div></section><section class="paper-card"><h2>إرسال بلاغ عن محتوى أو مخالفة</h2><div class="card-body"><form id="moderationForm"><div class="form-row"><div class="field"><label>نوع العنصر</label><select id="reportTargetKind"><option value="book">كتاب</option><option value="user">حساب مستخدم</option><option value="post">منشور</option><option value="group">مجموعة</option><option value="channel">قناة</option><option value="research">بحث</option><option value="other">أخرى</option></select></div><div class="field"><label>معرّف العنصر أو رابطه</label><input id="reportTargetId" required maxlength="200"></div><div class="field"><label>نوع المخالفة</label><select id="reportViolation"><option value="copyright">حقوق نشر</option><option value="misinformation">معلومة مضللة</option><option value="abuse">إساءة أو مضايقة</option><option value="spam">رسائل مزعجة</option><option value="other">أخرى</option></select></div></div><div class="field"><label>شرح البلاغ</label><textarea id="reportDescription" required minlength="5" maxlength="12000"></textarea></div><button class="btn secondary" type="submit">إرسال البلاغ للمراجعة</button></form></div></section></div>`}

function renderPlannedModule(){return `<div class="page-shell"><section class="paper-card"><h2>مكونات هذا القسم</h2><div class="card-body"><div class="notice-strip warning">هذا القسم مضاف إلى هيكل مكتبة القيّوم وخطة التنفيذ. وظائف الخادم وقاعدة البيانات لم تُفعّل بعد.</div><div class="grid-3"><div class="tool-tile"><b>بيانات موثقة</b><p>كل سجل يرتبط بمصدر وطبعة وموضع تحقق.</p></div><div class="tool-tile"><b>مراجعة بشرية</b><p>اقتراحات الأنظمة الآلية لا تعتمد قبل مراجعة المختص.</p></div><div class="tool-tile"><b>سجل التغييرات</b><p>حفظ حالة المراجعة وسبب التعديل وهوية المراجع.</p></div></div></div></section></div>`}
function eventDateLabel(value){if(!value)return '';try{return new Intl.DateTimeFormat('ar',{dateStyle:'full',timeStyle:'short'}).format(new Date(value))}catch{return value}}
async function loadPlatformPreferences(){if(!API_BASE||!apiToken())return;try{const d=await apiRequest('/api/preferences/platform');if($('#calendarMode')&&d.platform?.calendar_default)$('#calendarMode').value=d.platform.calendar_default;if($('#calendarAuthority')&&d.platform?.calendar_authority_mode)$('#calendarAuthority').value=d.platform.calendar_authority_mode;for(const box of $$('.notification-pref')){const pref=(d.notifications||[]).find(x=>x.notification_kind===box.dataset.kind);if(pref)box.checked=!!pref.in_app_enabled}}catch(err){console.warn('تعذر تحميل تفضيلات الحساب',err)}}
async function loadCalendarEvents(){const host=$('#calendarEventsList');if(!host)return;if(!API_BASE){host.textContent='اربط خادم القيّوم لعرض المناسبات المعتمدة.';return}try{const d=await apiRequest('/api/calendar/events');host.innerHTML=d.items.length?d.items.map(x=>`<article class="notice-strip"><b>${escapeHtml(x.title)}</b><p>${escapeHtml(x.hijri_date_label||'')} ${x.starts_at?' · '+escapeHtml(eventDateLabel(x.starts_at)):''}</p><p>${escapeHtml(x.description||'')}</p>${x.date_variation_note?`<small>${escapeHtml(x.date_variation_note)}</small>`:''}${x.source_title?`<small>المصدر: ${escapeHtml(x.source_title)}</small>`:''}</article>`).join(''):'<div class="empty-state">لا توجد مناسبات منشورة ضمن الفترة القادمة بعد.</div>'}catch(err){host.textContent=`تعذر تحميل المناسبات: ${err.message}`}}
async function loadNotifications(){const host=$('#notificationsList');if(!host)return;if(!API_BASE||!apiToken()){host.textContent='سجّل الدخول لعرض إشعارات حسابك.';return}try{const d=await apiRequest('/api/notifications');host.innerHTML=d.items.length?`<p class="muted">غير المقروء: ${Number(d.unreadCount)||0}</p>`+d.items.map(n=>`<article class="notice-strip ${n.read_at?'':'warning'}"><div class="toolbar" style="justify-content:space-between"><b>${escapeHtml(n.title)}</b>${n.read_at?'<span class="chip">مقروء</span>':`<button class="btn secondary" data-action="notification-read" data-id="${escapeHtml(n.id)}">تحديد كمقروء</button>`}</div><p>${escapeHtml(n.body||'')}</p><small>${escapeHtml(eventDateLabel(n.created_at))}</small></article>`).join(''):'<div class="empty-state">ما عندك إشعارات حالياً.</div>'}catch(err){host.textContent=`تعذر تحميل الإشعارات: ${err.message}`}}
async function loadMyModerationDecisions(){const host=$('#myModerationDecisions');if(!host||!API_BASE||!apiToken())return;try{const d=await apiRequest('/api/moderation/decisions/mine');const html=`<h3>القرارات والاستئناف</h3>${d.items.map(x=>`<article class="notice-strip"><b>${escapeHtml(x.decision_kind)} · ${escapeHtml(x.target_kind)}</b><p>${escapeHtml(x.reason)} · ${new Date(x.created_at).toLocaleDateString('ar')}</p><button class="btn secondary" data-action="appeal-submit" data-id="${x.id}">تقديم استئناف</button></article>`).join('')||'<p class="muted">لا توجد قرارات مسجلة بحق حسابك.</p>'}`;host.innerHTML=html}catch(err){host.textContent=`تعذر تحميل القرارات: ${err.message}`}}
