function renderPage(key){if(['admin','dashboard','staff'].includes(key)&&!sessionChecked){home.hidden=false;page.hidden=true;return}if(key==='dashboard'&&currentSession?.accountType!=='owner'){toast('مركز المالك مخصص للمالك فقط.');location.hash=currentSession?.isAdmin?'#admin':'#home';return}if(key==='admin'&&!currentSession?.isAdmin){toast('هذا القسم متاح للحسابات الإدارية المفعّلة فقط.');location.hash='#home';return}if(key==='staff'&&currentSession?.accountType!=='owner'){toast('إدارة الأقسام والموظفين متاحة للمالك فقط حالياً.');location.hash=currentSession?.isAdmin?'#admin':'#home';return}const renderers={assistant:renderAssistant,reader:renderReader,personal:renderPersonal,library:renderLibrary,history:renderLibrary,fiqh:renderLibrary,ahlulbayt:renderLibrary,aqaed:renderLibrary,quran:renderLibrary,ethics:renderLibrary,language:renderLibrary,research:renderResearch,hadith:renderHadith,calendar:renderCalendar,study:renderStudy,groups:renderGroups,notifications:renderNotifications,admin:renderAdminDashboard,dashboard:renderDashboard,login:renderLogin,settings:renderSettings,about:()=>`<div class="page-shell"><section class="paper-card"><h2>رسالة المكتبة</h2><div class="card-body"><p>مكتبة القيّوم مشروع علمي لفهرسة مصادر المعرفة الإسلامية، وإتاحة البحث والقراءة والتحقيق، مع احترام تعدد المدارس والمناهج واللغات وحقوق النشر.</p><p>تعتمد المكتبة التوثيق الببليوغرافي، وفصل النص المنقول عن التقييم والتحليل، وعدم نسبة كتاب أو رواية إلى مدرسة أو مؤلف دون دليل.</p></div></section></div>`,contact:renderContact,rijal:renderPlannedModule,comparative:renderPlannedModule,manuscripts:renderPlannedModule,ocr:renderPlannedModule,translations:renderPlannedModule,sources:renderPlannedModule,publishers:renderPlannedModule,digital:renderPlannedModule,logic:renderPlannedModule,quality:renderPlannedModule,staff:renderPlannedModule,projects:renderPlannedModule,usul:renderPlannedModule,economy:renderPlannedModule,society:renderPlannedModule,education:renderPlannedModule,geography:renderPlannedModule,law:renderPlannedModule,natural:renderPlannedModule,prayers:renderPlannedModule};
 if(key==='home'||!key){home.hidden=false;page.hidden=true;return}
 home.hidden=true;page.hidden=false;page.innerHTML=pageHeader(key)+(renderers[key]?renderers[key]():`<div class="page-shell"><div class="empty-state">هذا القسم سيُربط ضمن قاعدة بيانات المكتبة.</div></div>`);window.scrollTo({top:0,behavior:'smooth'});loadLocalNotes();if(key==='research')loadResearchProjects();else loadLocalProjects();if(key==='study'){loadStudyNotes()}if(key==='contact'){loadMySupportTickets()}if(key==='calendar'){loadCalendarEvents();loadPlatformPreferences()}if(key==='notifications'){loadNotifications();loadPlatformPreferences()}if(key==='groups'){loadCommunitySpaces()}}
function route(){const key=(location.hash||'#home').slice(1).split('?')[0];if(key==='sections'||key==='all-sections'){home.hidden=false;page.hidden=true;setTimeout(()=>$(key==='all-sections'?'#all-sections':'#sections')?.scrollIntoView({behavior:'smooth'}),0);return}renderPage(key);$$('#mainNav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===`#${key}`));nav.classList.remove('open');menuToggle.setAttribute('aria-expanded','false')}
function applyRoleNavigation(){const owner=currentSession?.accountType==='owner',admin=!!currentSession?.isAdmin;document.querySelectorAll('a[href="#dashboard"],a[href="#staff"]').forEach(a=>a.hidden=!owner);let adminLink=$('#roleAdminLink');if(admin&&!adminLink){adminLink=document.createElement('a');adminLink.id='roleAdminLink';adminLink.href='#admin';adminLink.textContent='▣ لوحة الإدارة';nav.append(adminLink)}if(adminLink)adminLink.hidden=!admin;const entry=$('.admin');if(entry){entry.href=owner?'#dashboard':admin?'#admin':'#login';entry.textContent=owner?'♛ مركز المالك':admin?'♟ لوحة الإدارة':'♟ دخول الحساب'} }
async function refreshSession(){currentSession=null;const token=apiToken();if(token&&API_BASE){try{currentSession=await apiRequest('/api/auth/me')}catch(err){sessionStorage.removeItem('qayyum-session-token');console.warn('انتهت صلاحية الجلسة أو الحساب',err)}}sessionChecked=true;applyRoleNavigation();return currentSession}
async function bootstrapSession(){if(apiToken()&&API_BASE)await refreshSession();else{sessionChecked=true;applyRoleNavigation()}route()}
